mapper.sql:
WHERE b.delete_yn = 'N'

  AND b.site_id = #{search.siteId}


  AND b.banner_location = #{search.bannerLocation}


  AND b.use_yn = #{search.useYn}


  AND b.banner_title LIKE CONCAT('%', #{search.keyword}, '%')

mapper.select:
SELECT MAX(sort_order)
  FROM tb_banner
 WHERE site_id         = #{siteId}
   AND banner_location = #{bannerLocation}

mapper.delete:
DELETE FROM tb_banner
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
